<script setup lang="ts">
import {onMounted,ref} from 'vue';import api from '../api';
const rows=ref<any[]>([]),clients=ref<any[]>([]),title=ref(''),number=ref(''),clientId=ref(''),area=ref('Cível'),status=ref('active'),court=ref(''),message=ref('');
async function load(){const [a,b]=await Promise.all([api.get('/cases'),api.get('/clients')]);rows.value=a.data.data;clients.value=b.data.data}
async function save(){try{await api.post('/cases',{title:title.value,case_number:number.value,client_id:Number(clientId.value),legal_area:area.value,status:status.value,court:court.value});title.value='';number.value='';court.value='';message.value='Processo cadastrado.';await load()}catch{message.value='Preencha os campos obrigatórios e selecione um cliente.'}}
async function remove(id:number){if(confirm('Excluir este processo?')){await api.delete(`/cases/${id}`);await load()}}
onMounted(load);
</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">CONTENCIOSO</p><h1>Processos</h1><p class="muted">Acompanhe os processos vinculados aos clientes.</p></div></div><div class="panel form-panel"><h2>Novo processo</h2><form class="inline-form" @submit.prevent="save"><label>Cliente<select v-model="clientId" required><option value="" disabled>Selecione</option><option v-for="c in clients" :value="String(c.id)">{{c.name}}</option></select></label><label>Número<input v-model="number" required placeholder="0000000-00.0000.0.00.0000"/></label><label>Título<input v-model="title" required placeholder="Descrição do processo"/></label><label>Área<select v-model="area"><option>Cível</option><option>Trabalhista</option><option>Tributária</option><option>Família</option><option>Empresarial</option></select></label><label>Tribunal<input v-model="court" placeholder="Ex.: TJES"/></label><label>Status<select v-model="status"><option value="active">Ativo</option><option value="pending">Pendente</option><option value="closed">Encerrado</option></select></label><button class="primary">Cadastrar processo</button></form><p v-if="message" class="muted">{{message}}</p></div><div class="panel"><div class="panel-heading"><h2>Processos cadastrados</h2></div><div class="table-wrap"><table><thead><tr><th>Número / título</th><th>Cliente</th><th>Área</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="c in rows" :key="c.id"><td><b>{{c.title}}</b><small>{{c.case_number}}</small></td><td>{{c.client?.name}}</td><td>{{c.legal_area}}</td><td><span class="status" :class="c.status">{{c.status}}</span></td><td><button class="danger-link" @click="remove(c.id)">Excluir</button></td></tr></tbody></table></div><p v-if="!rows.length" class="empty">Nenhum processo cadastrado.</p></div></section></template>
